import limited_client as robot,numpy as np
from scipy.spatial.transform import Rotation
def Rof(s):
 a=s['tcp_quaternion_wxyz'];return Rotation.from_quat([a[1],a[2],a[3],a[0]])
s=robot.observe()['robot'];q=np.array(s['joint_positions']);
for _ in range(4):robot.step(q.tolist()+[.04,.04]);s=robot.observe()['robot'];q=np.array(s['joint_positions'])
s=robot.observe()['robot'];q=np.array(s['joint_positions']);p=np.array(s['tcp_position']);rr=Rof(s); t=q.copy();t[6]+=.06
robot.step(t.tolist()+[.04,.04]);robot.step(t.tolist()+[.04,.04]);a=robot.observe()['robot']; den=a['joint_positions'][6]-q[6]; col=np.r_[(np.array(a['tcp_position'])-p)/den,(Rof(a)*rr.inv()).as_rotvec()/den]
for _ in range(5): robot.step(q.tolist()+[.04,.04])
print('q',q,'col6',col,'end',robot.observe()['robot'],'status',robot.status())
